source='''from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != background}
    for color in colors:
        for r in range(h):
            cols = [c for c in range(w) if grid[r][c] == color]
            if len(cols) >= 2:
                for c in range(min(cols), max(cols) + 1):
                    if grid[r][c] == background:
                        out[r][c] = 3
        for c in range(w):
            rows = [r for r in range(h) if grid[r][c] == color]
            if len(rows) >= 2:
                for r in range(min(rows), max(rows) + 1):
                    if grid[r][c] == background:
                        out[r][c] = 3
    return out
'''
